-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_hero_attribute AS SELECT hero_attribute.attribute_value AS attribute_value, superhero.superhero_name AS superhero_name, superhero.full_name AS full_name, superhero.eye_colour_id AS eye_colour_id, superhero.hair_colour_id AS hair_colour_id, superhero.skin_colour_id AS skin_colour_id, superhero.race_id AS race_id, superhero.alignment_id AS alignment_id, superhero.height_cm AS height_cm, superhero.weight_kg AS weight_kg, attribute.attribute_name AS attribute_name, gender.gender AS gender, publisher.publisher_name AS publisher_name FROM hero_attribute LEFT JOIN superhero ON hero_attribute.hero_id = superhero.id LEFT JOIN attribute ON hero_attribute.attribute_id = attribute.id LEFT JOIN gender ON superhero.gender_id = gender.id LEFT JOIN publisher ON superhero.publisher_id = publisher.id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_hero_power AS SELECT superhero.superhero_name AS superhero_name, superhero.full_name AS full_name, superhero.race_id AS race_id, superhero.alignment_id AS alignment_id, superhero.height_cm AS height_cm, superhero.weight_kg AS weight_kg, superpower.power_name AS power_name, gender.gender AS gender, eye_colour.colour AS eye_colour, hair_colour.colour AS hair_colour, skin_colour.colour AS skin_colour, publisher.publisher_name AS publisher_name FROM hero_power LEFT JOIN superhero ON hero_power.hero_id = superhero.id LEFT JOIN superpower ON hero_power.power_id = superpower.id LEFT JOIN gender ON superhero.gender_id = gender.id LEFT JOIN colour eye_colour ON superhero.eye_colour_id = eye_colour.id LEFT JOIN colour hair_colour ON superhero.hair_colour_id = hair_colour.id LEFT JOIN colour skin_colour ON superhero.skin_colour_id = skin_colour.id LEFT JOIN publisher ON superhero.publisher_id = publisher.id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_superhero AS SELECT superhero.id AS id, superhero.superhero_name AS superhero_name, superhero.full_name AS full_name, superhero.height_cm AS height_cm, superhero.weight_kg AS weight_kg, gender.gender AS gender, eye_colour.colour AS eye_colour, hair_colour.colour AS hair_colour, skin_colour.colour AS skin_colour, race.race AS race, publisher.publisher_name AS publisher_name, alignment.alignment AS alignment FROM superhero LEFT JOIN gender ON superhero.gender_id = gender.id LEFT JOIN colour eye_colour ON superhero.eye_colour_id = eye_colour.id LEFT JOIN colour hair_colour ON superhero.hair_colour_id = hair_colour.id LEFT JOIN colour skin_colour ON superhero.skin_colour_id = skin_colour.id LEFT JOIN race ON superhero.race_id = race.id LEFT JOIN publisher ON superhero.publisher_id = publisher.id LEFT JOIN alignment ON superhero.alignment_id = alignment.id;
